#!/bin/sh
set -eu
app_password="$(cat /run/secrets/postgres_app_password)"
# Password files must contain hex only, generated by the preparation script.
case "$app_password" in ''|*[!a-f0-9]*) echo "Invalid application password format" >&2; exit 1;; esac
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" --set=app_password="$app_password" <<'SQL'
CREATE ROLE agt_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION PASSWORD :'app_password';
GRANT CONNECT ON DATABASE agtgestor TO agt_app;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO agt_app;
SQL
